class Futarchy:
    program_id = PROGRAM_ID

    # ------------------------------- errors ------------------------------- #
    # Defined by the program (IDL `errors[]`). Catch `Futarchy.Error`
    # to match any of them; each is also importable from this module.
    class Error(ProgramError):
        """Base for every futarchy program error — catch it to match any of them."""

    class AmmTooOld(Error):
        code = 6000
        msg = 'Amms must have been created within 5 minutes (counted in slots) of proposal initialization'

    class InvalidInitialObservation(Error):
        code = 6001
        msg = "An amm has an `initial_observation` that doesn't match the `dao`'s config"

    class InvalidMaxObservationChange(Error):
        code = 6002
        msg = "An amm has a `max_observation_change_per_update` that doesn't match the `dao`'s config"

    class InvalidStartDelaySlots(Error):
        code = 6003
        msg = "An amm has a `start_delay_slots` that doesn't match the `dao`'s config"

    class InvalidSettlementAuthority(Error):
        code = 6004
        msg = 'One of the vaults has an invalid `settlement_authority`'

    class ProposalTooYoung(Error):
        code = 6005
        msg = 'Proposal is too young to be executed or rejected'

    class MarketsTooYoung(Error):
        code = 6006
        msg = 'Markets too young for proposal to be finalized. TWAP might need to be cranked'

    class ProposalAlreadyFinalized(Error):
        code = 6007
        msg = 'This proposal has already been finalized'

    class InvalidVaultNonce(Error):
        code = 6008
        msg = 'A conditional vault has an invalid nonce. A nonce should encode the proposal number'

    class ProposalNotPassed(Error):
        code = 6009
        msg = "This proposal can't be executed because it isn't in the passed state"

    class InsufficientLiquidity(Error):
        code = 6010
        msg = 'More liquidity needs to be in the AMM to launch this proposal'

    class ProposalDurationTooShort(Error):
        code = 6011
        msg = 'Proposal duration must be longer 1 day and longer than 2 times the TWAP start delay'

    class PassThresholdTooHigh(Error):
        code = 6012
        msg = 'Pass threshold must be less than 10%'

    class QuestionMustBeBinary(Error):
        code = 6013
        msg = 'Question must have exactly 2 outcomes for binary futarchy'

    class InvalidSquadsProposalStatus(Error):
        code = 6014
        msg = 'Squads proposal must be in Active status'

    class CastingOverflow(Error):
        code = 6015
        msg = "Casting overflow. If you're seeing this, please report this"

    class InsufficientBalance(Error):
        code = 6016
        msg = 'Insufficient balance'

    class ZeroLiquidityRemove(Error):
        code = 6017
        msg = 'Cannot remove zero liquidity'

    class SwapSlippageExceeded(Error):
        code = 6018
        msg = 'Swap slippage exceeded'

    class AssertFailed(Error):
        code = 6019
        msg = 'Assert failed'

    class InvalidAdmin(Error):
        code = 6020
        msg = 'Invalid admin'

    class ProposalNotInDraftState(Error):
        code = 6021
        msg = 'Proposal is not in draft state'

    class InsufficientTokenBalance(Error):
        code = 6022
        msg = 'Insufficient token balance'

    class InvalidAmount(Error):
        code = 6023
        msg = 'Invalid amount'

    class InsufficientStakeToLaunch(Error):
        code = 6024
        msg = 'Insufficient stake to launch proposal'

    class StakerNotFound(Error):
        code = 6025
        msg = 'Staker not found in proposal'

    class PoolNotInSpotState(Error):
        code = 6026
        msg = 'Pool must be in spot state'

    class InvalidDaoCreateLiquidity(Error):
        code = 6027
        msg = "If you're providing liquidity, you must provide both base and quote token accounts"

    class InvalidStakeAccount(Error):
        code = 6028
        msg = 'Invalid stake account'

    class InvariantViolated(Error):
        code = 6029
        msg = 'An invariant was violated. You should get in contact with the MetaDAO team if you see this'

    class ProposalNotActive(Error):
        code = 6030
        msg = 'Proposal needs to be active to perform a conditional swap'

    class InvalidTransaction(Error):
        code = 6031
